int add(int a, int b) {
    int result = a + b;     // one variable
    return result;
}

int sumArray(vector<int>& arr) {
    int total = 0;             // one variable
    for (int i = 0; i < (int)arr.size(); i++) {
        total += arr[i];   // no new memory created
    }
    return total;
}

vector<int> doubleArray(vector<int>& arr) {
    vector<int> result;
    for (int item : arr) {
        result.push_back(item * 2);
    }
    return result;
}

unordered_map<int,int> countElements(vector<int>& arr) {
    unordered_map<int,int> counts;
    for (int item : arr) {
        counts[item]++;
    }
    return counts;
}

bool hasDuplicate(vector<int>& arr) {
    unordered_set<int> seen;
    for (int item : arr) {
        if (seen.count(item)) return true;
        seen.insert(item);
    }
    return false;
}

vector<vector<int>> createGrid(int n) {
    vector<vector<int>> grid;
    for (int i = 0; i < n; i++) {
        vector<int> row(n, 0);
        grid.push_back(row);
    }
    return grid;
}

void countdown(int n) {
    if (n == 0) return;
    countdown(n - 1);
}

int fib(int n) {
    if (n <= 1) return n;
    return fib(n - 1) + fib(n - 2);
}

int binarySearch(vector<int>& arr, int low, int high, int target) {
    if (low > high) return -1;
    int mid = (low + high) / 2;
    if (arr[mid] == target) return mid;
    else if (arr[mid] < target)
        return binarySearch(arr, mid + 1, high, target);
    else
        return binarySearch(arr, low, mid - 1, target);
}

vector<int> reverseList(vector<int> lst) {
    if (lst.empty()) return {};
    int last = lst.back();
    lst.pop_back();
    vector<int> rest = reverseList(lst);
    rest.insert(rest.begin(), last);
    return rest;
}

vector<int> twoSumSlow(vector<int>& arr, int target) {
    for (int i = 0; i < (int)arr.size(); i++) {          // O(n)
        for (int j = i + 1; j < (int)arr.size(); j++) {  // O(n)
            if (arr[i] + arr[j] == target)
                return {i, j};
        }
    }
    return {};
}
// Time: O(n^2)   Space: O(1)

vector<int> twoSumFast(vector<int>& arr, int target) {
    unordered_map<int,int> seen;         // extra memory
    for (int i = 0; i < (int)arr.size(); i++) {
        int complement = target - arr[i];
        if (seen.count(complement))
            return {seen[complement], i};
        seen[arr[i]] = i;
    }
    return {};
}
// Time: O(n)   Space: O(n)

